async function extract(ctx) {
  // The shell page no longer carries `data-player-tvid`, so the engine has nothing to start from.
  // The player instance does hold the signed playlist once it has negotiated playback.
  const win = (ctx && ctx.window) || window;
  const deadline = Date.now() + 12000;

  function scan() {
    const mv = win.playback && win.playback.msePlayback && win.playback.msePlayback._mvInfo;
    if (!mv) return null;
    let best = null;
    for (const bucket of [mv.levelInfoArr, mv.videoList, mv.dolbyInfoArr, mv.hdrInfoArr]) {
      if (!bucket) continue;
      for (const entry of Object.values(bucket)) {
        if (!entry || typeof entry.ml !== 'string') continue;
        if (!/^https?:\/\/[^"']+\.m3u8/i.test(entry.ml)) continue;
        const score = Number(entry.vf) || 0;
        if (!best || score > best.score) best = { url: entry.ml, score, label: entry.vd || '' };
      }
    }
    return best;
  }

  while (Date.now() < deadline) {
    const hit = scan();
    if (hit) {
      return {
        directUrl: hit.url,
        title: String(document.title || '').split(/[-_|]/)[0].trim(),
        quality: hit.label,
        ext: 'mp4',
        headers: { referer: location.href, 'user-agent': navigator.userAgent },
      };
    }
    await new Promise((resolve) => setTimeout(resolve, 400));
  }

  throw new Error('播放器没有暴露播放地址：先确认页面能正常播放，再运行适配器');
}
